void append_checksum_to_control_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed || skb->ip_summed != CHECKSUM_COMPLETE)
        return;

    if (offset > 0) {
        skb->csum = csum_partial(skb->data + tlen, offset, skb->csum);
    }

    msg->msg_control = skb->csum;
}

void append_checksum_to_ctl_msg(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb->ip_summed) {
        return;
    }

    if (offset > 0) {
        skb->csum = csum_partial(skb->data + tlen, skb->len - tlen, skb->csum);
    }

    msg->msg_controllen = CMSG_SPACE(sizeof(__u32));
    *(__u32 *)CMSG_DATA(&msg->msg_control) = skb->csum;
}

