void append_checksum_to_message(struct msghdr *msg, struct sk_buff *skb, int tlen, int offset) {
    if (!skb_checksum_complete(skb))
        return;

    if (offset > 0)
        skb->csum = csum_partial(skb->data + tlen, skb->len - tlen, skb->csum, offset, skb->data);

    msg->msg_control = skb->csum;
}
